const N = 3, MAX = 6, IMG = ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
const NM = ['Pez labios', 'Gato pez', 'Pez con zapatillas', 'Langosta azul', 'Pulpo', 'La cima'];
const SV = '<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 15l7-7 7 7"/></svg>';
const $ = s => document.querySelector(s);
const layer = $('#tiles'), chain = $('#chain'), ov = $('#ov'), dpad = $('#dpad'), tp = $('#tp');
let tiles = [], uid = 0, score = 0, best = 0, top = 1, busy = false, won = false, over = false;
try { best = +localStorage.getItem('pm-best') || 0 } catch (e) { }

$('#grid').innerHTML = '<i></i>'.repeat(9);
IMG.forEach((s, i) => { const li = document.createElement('li'), im = new Image(); im.src = s; im.alt = NM[i]; li.title = NM[i]; li.append(im); chain.append(li) });

function paint(t, cls, delay) {
    const im = new Image();
    im.src = IMG[t.v - 1]; im.alt = NM[t.v - 1]; im.draggable = false;
    if (cls) im.className = cls;
    if (delay) im.style.animationDelay = delay + 'ms';
    t.el.className = 't v' + t.v;
    t.el.replaceChildren(im);
}
function mk(v, r, c, cls, delay) {
    const el = document.createElement('div');
    el.style.setProperty('--r', r); el.style.setProperty('--c', c);
    const t = { id: ++uid, v, r, c, el, m: false };
    paint(t, cls, delay);
    layer.append(el); tiles.push(t);
    return t;
}
function sync() {
    $('#sc').textContent = score;
    if (score > best) { best = score; try { localStorage.setItem('pm-best', best) } catch (e) { } }
    $('#bs').textContent = best;
    [...chain.children].forEach((li, i) => li.classList.toggle('on', i < top));
}
function show(title, text, cont) {
    $('#mt').textContent = title; $('#mp').textContent = text;
    $('#mk').hidden = !cont; ov.classList.add('on');
}
function canMove() {
    if (tiles.length < N * N) return true;
    const at = (r, c) => tiles.find(t => t.r === r && t.c === c);
    for (let r = 0; r < N; r++)for (let c = 0; c < N; c++) {
        const v = at(r, c).v;
        if (v < MAX && ((c + 1 < N && at(r, c + 1).v === v) || (r + 1 < N && at(r + 1, c).v === v))) return true;
    }
    return false;
}
function start() {
    tiles.forEach(t => t.el.remove()); tiles = [];
    score = 0; top = 1; busy = false; won = false; over = false;
    ov.classList.remove('on');
    for (let i = 0; i < N * N; i++)mk(1, (i / N) | 0, i % N, 'sp', i * 45);
    sync();
}
/* d: 0 izquierda, 1 arriba, 2 derecha, 3 abajo */
function move(d) {
    if (busy || over || ov.classList.contains('on')) return;
    const g = Array.from({ length: N }, () => Array(N).fill(null));
    tiles.forEach(t => { g[t.r][t.c] = t });
    const gone = [], ups = []; let moved = false;
    for (let i = 0; i < N; i++) {
        const pos = [...Array(N).keys()].map(k => d === 0 ? [i, k] : d === 2 ? [i, N - 1 - k] : d === 1 ? [k, i] : [N - 1 - k, i]);
        let k = 0, last = null;
        for (const [r, c] of pos) {
            const t = g[r][c];
            if (!t) continue;
            if (last && !last.m && last.v === t.v && t.v < MAX) {
                t.r = last.r; t.c = last.c; last.m = true;
                gone.push(t); ups.push(last); moved = true;
            } else {
                const [nr, nc] = pos[k++];
                if (nr !== t.r || nc !== t.c) moved = true;
                t.r = nr; t.c = nc; last = t;
            }
        }
    }
    if (!moved) return;
    busy = true;
    tiles.forEach(t => { t.el.style.setProperty('--r', t.r); t.el.style.setProperty('--c', t.c) });
    setTimeout(() => {
        gone.forEach(t => t.el.remove());
        tiles = tiles.filter(t => !gone.includes(t));
        ups.forEach(t => { t.v++; t.m = false; score += 2 ** t.v; top = Math.max(top, t.v); paint(t, 'pp') });
        const free = [];
        for (let r = 0; r < N; r++)for (let c = 0; c < N; c++)if (!tiles.some(t => t.r === r && t.c === c)) free.push([r, c]);
        if (free.length) { const [r, c] = free[Math.random() * free.length | 0]; mk(1, r, c, 'sp') }
        busy = false; sync();
        if (!won && top >= MAX) { won = true; show('¡Llegaste a la cima!', 'Fusionaste a toda la cadena. Puedes seguir sumando puntos.', true) }
        else if (!canMove()) { over = true; show('Sin movimientos', 'Terminaste con ' + score + ' puntos.', false) }
    }, 150);
}

/* Botones de dirección (opcionales) */
[['1', 'Arriba'], ['0', 'Izquierda'], ['3', 'Abajo'], ['2', 'Derecha']].forEach(([d, l]) => {
    const b = document.createElement('button');
    b.dataset.d = d; b.setAttribute('aria-label', l); b.innerHTML = SV;
    b.onclick = () => move(+d); dpad.append(b);
});
function setPad(on) {
    document.body.classList.toggle('dp', on);
    tp.setAttribute('aria-pressed', on); dpad.hidden = !on;
    try { localStorage.setItem('pm-pad', on ? '1' : '0') } catch (e) { }
}
tp.onclick = () => setPad(!document.body.classList.contains('dp'));
try { if (localStorage.getItem('pm-pad') === '1') setPad(true) } catch (e) { }

/* Swipes (táctil y ratón) */
let sx = 0, sy = 0, tr = false;
addEventListener('pointerdown', e => { if (e.target.closest('button')) return; sx = e.clientX; sy = e.clientY; tr = true });
addEventListener('pointermove', e => {
    if (!tr) return;
    const dx = e.clientX - sx, dy = e.clientY - sy;
    if (Math.max(Math.abs(dx), Math.abs(dy)) < 28) return;
    tr = false;
    move(Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? 0 : 2) : (dy < 0 ? 1 : 3));
});
addEventListener('pointerup', () => { tr = false });
addEventListener('pointercancel', () => { tr = false });
addEventListener('keydown', e => {
    const d = { ArrowLeft: 0, a: 0, A: 0, ArrowUp: 1, w: 1, W: 1, ArrowRight: 2, d: 2, D: 2, ArrowDown: 3, s: 3, S: 3 }[e.key];
    if (d !== undefined) { e.preventDefault(); move(d) }
});
$('#nw').onclick = start; $('#mn').onclick = start;
$('#mk').onclick = () => ov.classList.remove('on');
start();